<?php
declare(strict_types=1);
namespace ReadyFinance;
final class RecurrenceService {
 public function __construct(private Core $c){}
 public function create(int $h,int $u,array $p,string $uuid):void {
  $c=$this->c;$row=['uuid'=>$uuid,'household_id'=>$h];
  $cat=$c->scope('categories',$p['category_uuid']??'',$h);if(!(int)($c->one('SELECT * FROM ledger_accounts WHERE household_id=? AND id=?',[$h,$cat['ledger_id']])['active']??1))throw new Fault('Restore this expense account first.');if($cat['type']!=='expense')throw new Fault('Choose an expense category.');$freq=$p['frequency']??'monthly';if(!in_array($freq,['weekly','monthly','yearly'],true))throw new Fault('Choose weekly monthly or yearly.');$date=Core::date($p['next_date']??'');$c->insert('recurring_rules',$row+['name'=>Core::text($p['name']??''),'amount'=>Core::money($p['amount']??''),'category_id'=>$cat['id'],'frequency'=>$freq,'next_date'=>$date,'anchor_day'=>(int)substr($date,8,2)]);
 }
 public function runRecurring(int $h,int $u):array {
  return $this->c->atomic(function()use($h,$u){$c=$this->c;$c->one('SELECT id FROM households WHERE id=? FOR UPDATE',[$h]);$today=$c->today($h);$planning=(new PlanManagementService($c))->ready();$count=0;foreach($c->all('SELECT * FROM recurring_rules WHERE household_id=? AND active=1'.($planning?' AND archived=0':'').' AND next_date<=? FOR UPDATE',[$h,$today]) as $r){$date=$r['next_date'];while($date<=$today&&$count<100){if(!$c->one('SELECT bill_id FROM recurring_occurrences WHERE rule_id=? AND occurrence_date=?',[$r['id'],$date])){$bid=$c->insert('bills',['uuid'=>Core::uuid(),'household_id'=>$h,'name'=>$r['name'],'amount'=>$r['amount'],'due_date'=>$date,'category_id'=>$r['category_id'],'created_at'=>Core::now()]);$c->insert('recurring_occurrences',['rule_id'=>$r['id'],'occurrence_date'=>$date,'bill_id'=>$bid]);$count++;}$d=new \DateTimeImmutable($date);if($r['frequency']==='weekly')$date=$d->modify('+7 days')->format('Y-m-d');else{$d=$d->modify('first day of this month')->modify($r['frequency']==='yearly'?'+1 year':'+1 month');$date=$d->setDate((int)$d->format('Y'),(int)$d->format('m'),min((int)$r['anchor_day'],(int)$d->format('t')))->format('Y-m-d');}}$c->query('UPDATE recurring_rules SET next_date=?'.($planning?',row_version=row_version+1,updated_at=UTC_TIMESTAMP(6)':'').' WHERE id=?',[$date,$r['id']]);}$c->audit($h,$u,'recurring.generated',null,['count'=>$count]);return ['generated'=>$count];});
 }}
